protocol Shape { func area() -> Double }

func largest<S: Shape>(_ shapes: [S]) -> S? {        // all the same type
    shapes.max { $0.area() < $1.area() }
}

func makeShape() -> some Shape { Circle(r: 2) }      // hidden but fixed type

func totalArea(_ shapes: [any Shape]) -> Double {    // mixed types
    shapes.reduce(0) { $0 + $1.area() }
}
